{
 "questions": [
  {
   "question": "Which problem do you want to build the brief around? (Each one avoids the two example problems in project.txt and has a natural split between AI and deterministic code.)",
   "header": "Problem",
   "multiSelect": false,
   "options": [
    {
     "label": "Loan covenant checks (Recommended)",
     "description": "Each credit agreement defines 'EBITDA' or 'Leverage' in its own way. The LLM turns the defined-terms clause into a formula a human approves once. After that, a deterministic engine runs it on each quarter's financials, and every number traces back to a clause. The idea that stands out: the LLM acts as a compiler, not a calculator."
    },
    {
     "label": "Withholding tax on foreign payments",
     "description": "Example: an Indian SME pays a foreign SaaS or consulting vendor. Is the payment a royalty, fees for technical services, or business profits under the tax treaty (e.g. the 'make available' clause in India\u2013US)? The LLM classifies it and cites the clause, a rules table gives the rate, and a CA has to sign Form 15CB by law, so the human-in-the-loop step is required rather than added for show."
    },
    {
     "label": "Tax notice triage",
     "description": "A taxpayer receives an automated mismatch notice (e.g. an Indian s.143(1) notice or a US CP2000). The AI explains the mismatch against the taxpayer's own documents and drafts a response for a professional to review."
    },
    {
     "label": "I have my own idea",
     "description": "Tell me the area or problem and I'll plan around it."
    }
   ]
  },
  {
   "question": "How far should the prototype go? (Section 2, step 3 is optional.)",
   "header": "Prototype",
   "multiSelect": false,
   "options": [
    {
     "label": "Small Python prototype (Recommended)",
     "description": "A notebook or CLI using an OpenRouter free model, run on 10+ synthetic examples with an honest table of where it fails, plus a README."
    },
    {
     "label": "Clickable mock only",
     "description": "A static HTML mock showing the flow, with no live model calls."
    },
    {
     "label": "Brief only, no prototype",
     "description": "Put all the effort into the 4-page brief and the appendix."
    }
   ]
  },
  {
   "question": "Which jurisdiction should the solution cover?",
   "header": "Jurisdiction",
   "multiSelect": false,
   "options": [
    {
     "label": "India",
     "description": "Indian tax and regulatory rules (Income Tax Act, GST, RBI, DTAAs)."
    },
    {
     "label": "US",
     "description": "US federal rules (IRS, SEC, and so on)."
    },
    {
     "label": "UK / EU",
     "description": "HMRC, FCA, or EU rules."
    },
    {
     "label": "Doesn't matter",
     "description": "Pick whichever fits the problem best."
    }
   ]
  }
 ]
}
