106:<script>
<script>
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const state = { idx: 0, doc: "notice", hl: null, guard: false, audit: {} };

function money(j, n){ if(n==null) return "?"; const R=RULES[j]; return R.currency + Number(n).toLocaleString(R.locale); }
function cite(ref, bad){ const [d,l]=ref.split(":"); return `<button class="cite${bad?' badcite':''}" data-doc="${d}" data-line="${l}" title="Show source">${esc(d)}:L${l}</button>`; }
function recCite(c, id){ const r=c.records.find(x=>x.id===id); return r? cite(`${r.doc}:${r.line}`) : `<span class="cite badcite">${esc(id)}?</span>`; }

// ───────── deterministic engine (this is real code, not canned) ─────────
function run(c, guard){
  const R = RULES[c.j]; const out = { checks: [], items: [], valid: true };
  const recs = Object.fromEntries(c.records.map(r=>[r.id,r]));

  // Stage 2: validate extraction
  const unreadable = c.items.filter(i=>i.reported==null||i.onReturn==null);
  out.checks.push({ ok: !unreadable.length, text: unreadable.length ? `${unreadable.length} line item(s) have unreadable amounts` : "All extracted amounts parsed as numbers", src: unreadable[0]?.src });
  const sum = c.items.reduce((s,i)=>s+((i.reported??0)-(i.onReturn??0)),0);
  out.checks.push({ ok: sum===c.notice.statedTotal, text: `Sum of line variances ${money(c.j,sum)} = notice's stated total ${money(c.j,c.notice.statedTotal)}`, src: c.notice.totalSrc });
  const yr = R.supportedYears.includes(c.notice.year);
  out.checks.push({ ok: yr, text: yr ? `${c.notice.yearText} is covered by rules table ${RULES.version}` : `${c.notice.yearText} is NOT covered by the rules table: refuse` });
  out.checks.push({ ok: !!(c.notice.issued || c.notice.respondBy), text: c.notice.issued || c.notice.respondBy ? "Issue / response date extracted" : "Issue date unreadable: deadline unknown" , src: "notice:3"});
  out.valid = out.checks.every(x=>x.ok);
  if(!out.valid) return out;

  // Stage 3: reproduce the notice from the taxpayer's own documents
  const consumed = new Set(c.matchedByNotice||[]);
  for(const it of c.items){
    const tp = c.records.filter(r=>r.kind==="third_party" && r.payer===it.payer && r.cat===it.cat);
    const rt = c.records.filter(r=>r.kind==="return" && r.payer===it.payer && r.cat===it.cat);
    rt.forEach(r=>consumed.add(r.id));
    const tpSum = tp.reduce((s,r)=>s+r.amount,0), rtSum = rt.reduce((s,r)=>s+r.amount,0);
    out.items.push({ it, delta: it.reported-it.onReturn, tp, rt, tpSum, rtSum, reproOk: tpSum===it.reported && rtSum===it.onReturn });
  }

  // Stage 4: rules engine judges each LLM proposal
  const usedAsAmount = new Set();
  for(const x of out.items){
    const props = (c.causes[x.it.id]||[]); let explained = 0; x.props = []; x.flags = [];
    for(const p of props){
      const rule = R.labels[p.label]; const v = { p, rule, ok: true, why: [], amount: 0 };
      if(!rule){ v.ok=false; v.why.push(`'${p.label}' is not in the closed taxonomy for ${R.name}`); }
      else {
        if(rule.exemptCategories){
          const e = rule.exemptCategories.find(e=>e.category===x.it.cat);
          if(!e) { v.ok=false; v.why.push(`${rule.id}: '${x.it.cat}' is not an exempt category`); }
          else if((e.fromYear!=null && c.notice.year<e.fromYear) || (e.toYear!=null && c.notice.year>e.toYear)){
            v.ok=false; v.why.push(`${rule.id}: exemption not available for ${c.notice.yearText}. ${e.ref}`);
          }
        }
        if(rule.requiresKind && ![...(p.amountFrom||[]),...(p.support||[])].some(id=>recs[id]?.kind===rule.requiresKind)){
          v.ok=false; v.why.push(`${rule.id}: requires evidence of type '${rule.requiresKind}', none supplied`);
        }
        if(rule.requiresSupportKinds && !(p.support||[]).some(id=>rule.requiresSupportKinds.includes(recs[id]?.kind))){
          v.ok=false; v.why.push(`${rule.id}: requires supporting evidence of type ${rule.requiresSupportKinds.join(" / ")}`);
        }
        if(p.remainder && !rule.remainderAllowed){ v.ok=false; v.why.push(`${rule.id}: label may not absorb a remainder`); }
        for(const id of (p.amountFrom||[])){
          if(!recs[id]) { v.ok=false; v.why.push(`evidence '${id}' does not exist`); continue; }
          if(guard && (consumed.has(id) || usedAsAmount.has(id))){ v.ok=false; v.why.push(`Ledger guard: ${recs[id].doc}:L${recs[id].line} already accounts for income matched elsewhere`); }
        }
      }
      if(v.ok){
        v.amount = p.remainder ? x.delta - explained : (p.amountFrom||[]).reduce((s,id)=>s+recs[id].amount,0);
        if(p.remainder && v.amount<=0){ v.ok=false; v.why.push("Nothing left for the remainder to explain"); }
      }
      if(v.ok){
        explained += v.amount; (p.amountFrom||[]).forEach(id=>usedAsAmount.add(id));
        if(rule.conflictKind){
          const hit = c.records.find(r=>r.kind===rule.conflictKind && r.payer===x.it.payer);
          if(hit) x.flags.push({ type:"conflict", text: rule.conflictMsg, src: `${hit.doc}:${hit.line}` });
        }
        if(rule.judgement) x.flags.push({ type:"judgement", text: `${rule.id}: ${rule.warn || rule.action}` });
        if(p.remainder) x.flags.push({ type:"judgement", text: `Remainder of ${money(c.j,v.amount)} accepted as '${rule.name}'; reviewer must confirm.` });
        if(p.confidence < 0.65) x.flags.push({ type:"judgement", text: `Low model confidence (${p.confidence.toFixed(2)})` });
      }
      x.props.push(v);
    }
    x.explained = explained; x.residue = x.delta - explained;
    const anyRejected = x.props.some(v=>!v.ok);
    x.status = x.residue!==0 ? "residue" : x.flags.some(f=>f.type==="conflict") ? "conflict" : (x.flags.length||anyRejected) ? "review" : "closed";
    x.responses = [...new Set(x.props.filter(v=>v.ok).map(v=>v.rule.response))];
    if(x.residue===x.delta && anyRejected && R.labels.genuinely_omitted) x.suggest = "Rules engine: no valid explanation survives. Likely 'genuinely omitted' (Agree); reviewer to confirm.";
  }
  const blockers = out.items.filter(x=>x.status==="residue"||x.status==="conflict"||!x.reproOk);
  out.draftAllowed = blockers.length===0 && !!c.draft;
  const resp = out.items.flatMap(x=>x.responses);
  out.overall = !resp.length ? "-" : resp.every(r=>r==="Agree") ? "Agree" : resp.every(r=>r==="Disagree") ? "Disagree" : "Partially agree";

  // Draft checks: every citation resolves; every currency amount traces to an extracted figure
  if(c.draft){
    const allowed = new Set();
    c.items.forEach(i=>{ allowed.add(i.reported); allowed.add(i.onReturn); allowed.add(i.reported-i.onReturn); });
    c.records.forEach(r=>allowed.add(r.amount));
    out.items.forEach(x=>x.props.forEach(v=>v.ok && allowed.add(v.amount)));
    const cites = [...c.draft.matchAll(/\{\{(\w+):(\d+)\}\}/g)].map(m=>({ref:`${m[1]}:${m[2]}`, ok: !!c.docs[m[1]] && +m[2]>=1 && +m[2]<=c.docs[m[1]].lines.length}));
    const amts = [...c.draft.matchAll(/[₹$]\s?([\d,]+)/g)].map(m=>{ const n=+m[1].replace(/,/g,""); return {n, ok: allowed.has(n)}; });
    out.draftChecks = { cites, amts };
  }
  return out;
}

function deadline(c){
  const R = RULES[c.j];
  let d = null;
  if(R.deadline.type==="printed") d = c.notice.respondBy;
  else if(c.notice.issued){ const t=new Date(c.notice.issued+"T00:00:00"); t.setDate(t.getDate()+R.deadline.days); d=t.toISOString().slice(0,10); }
  if(!d) return { text: "unknown", days: null };
  const days = Math.round((new Date(d+"T00:00:00") - new Date(new Date().toDateString()))/86400000);
  return { text: d, days };
}

function log(c, msg){ (state.audit[c.id] ||= []).push(`${new Date().toISOString().replace("T"," ").slice(0,19)}Z  ${msg}`); }

// ───────── rendering ─────────
function renderNav(){
  const g = j => CASES.map((c,i)=>c.j!==j?"":`<button class="${i===state.idx?'on':''}" data-i="${i}"><span class="cid">${c.id}</span><span class="ct">${esc(c.title)}</span></button>`).join("");
  $("#nav").innerHTML = `<div class="grp">India · s.143(1)(a)</div>${g("IN")}<div class="grp">US · CP2000</div>${g("US")}`;
}

function render(){
  const c = CASES[state.idx], R = RULES[c.j], o = run(c, state.guard), dl = deadline(c);
  if(!state.audit[c.id]){
    log(c, `extract   notice + ${Object.keys(c.docs).length-1} taxpayer docs (LLM output: canned fixture, no model called)`);
    log(c, `validate  ${o.valid ? "PASS" : "FAIL: " + o.checks.filter(x=>!x.ok).map(x=>x.text).join("; ")}`);
    log(c, `rules     table ${RULES.version} (${RULES.reviewedBy})`);
  }
  const yrs = dl.days==null ? "" : dl.days<0 ? `<span class="tag bad">${-dl.days} days overdue</span>` : `<span class="tag ${dl.days<=7?'bad':'warn'}">${dl.days} days left</span>`;
  let h = `<div class="card">
    <div class="verdict"><b style="font-size:16px">${c.id}: ${esc(c.title)}</b><span class="tag warn">SYNTHETIC</span></div>
    <div class="kpis" style="margin-top:6px">
      <span><span class="muted">Jurisdiction</span> <b>${R.name}</b></span>
      <span><span class="muted">Notice</span> <b>${esc(c.notice.type)}</b> ${c.notice.yearText}</span>
      <span><span class="muted">Respond by</span> <b>${dl.text}</b> ${yrs}</span>
    </div>
    <div class="small muted" style="margin-top:4px">Deadline rule: ${esc(R.deadline.ref)}</div>
  </div>`;

  // Stage 1
  h += `<section class="card stage llm"><h2>1 · Extract notice line items <span class="tag llm">LLM structured output</span></h2>
    <table><tr><th>Item</th><th>Payer</th><th class="num">Reported by 3rd party</th><th class="num">On return</th><th class="num">Variance</th><th>Source</th></tr>
    ${c.items.map(i=>`<tr><td>${esc(i.desc)}</td><td>${esc(i.payer)}</td><td class="num">${money(c.j,i.reported)}</td><td class="num">${money(c.j,i.onReturn)}</td><td class="num">${i.reported==null?"?":money(c.j,i.reported-i.onReturn)}</td><td>${cite(i.src)}</td></tr>`).join("")}
    </table><div class="small muted" style="margin-top:6px">Every field carries a source span. Taxpayer documents are extracted the same way (${c.records.length} records).</div></section>`;

  // Stage 2
  h += `<section class="card stage det"><h2>2 · Validate extraction <span class="tag det">deterministic</span> ${o.valid?'<span class="tag ok">pass</span>':'<span class="tag bad">stop: human re-key</span>'}</h2>
    <ul class="checks">${o.checks.map(x=>`<li><span class="ic ${x.ok?'ok':'bad'}">${x.ok?'✓':'✗'}</span><span>${esc(x.text)} ${x.src?cite(x.src):""}</span></li>`).join("")}</ul></section>`;

  if(!o.valid){
    h += reviewerQs(c);
  } else {
    // Stage 3
    h += `<section class="card stage det"><h2>3 · Reproduce the notice from the taxpayer's documents <span class="tag det">deterministic matcher</span></h2>
      <table><tr><th>Item</th><th class="num">Notice: reported</th><th>Taxpayer's copy</th><th class="num">Notice: on return</th><th>Filed return</th><th></th></tr>
      ${o.items.map(x=>`<tr><td>${esc(x.it.desc)}</td>
        <td class="num">${money(c.j,x.it.reported)}</td><td>${money(c.j,x.tpSum)} ${x.tp.map(r=>cite(`${r.doc}:${r.line}`)).join("")}</td>
        <td class="num">${money(c.j,x.it.onReturn)}</td><td>${money(c.j,x.rtSum)} ${x.rt.map(r=>cite(`${r.doc}:${r.line}`)).join("")||'<span class="muted small">no line for this payer + category</span>'}</td>
        <td>${x.reproOk?'<span class="tag ok">reproduced</span>':'<span class="tag bad">cannot reproduce</span>'}</td></tr>`).join("")}
      </table><div class="small muted" style="margin-top:6px">Join key: payer + income category. If the notice's figures can't be rebuilt from the taxpayer's own copies, nothing downstream is trusted.</div></section>`;

    // Stage 4
    h += `<section class="card stage mix"><h2>4 · Explain each variance <span class="tag llm">LLM proposes label + evidence</span><span class="tag det">rules table decides</span></h2>
      ${o.items.map(x=>`
        <div class="verdict"><b>${esc(x.it.desc)}</b> <span class="muted">variance ${money(c.j,x.delta)} · explained ${money(c.j,x.explained)} · residue <b>${money(c.j,x.residue)}</b></span>
          ${statusTag(x.status)}</div>
        ${x.props.length? "" : '<div class="notice warn">No proposal from the model.</div>'}
        ${x.props.map(v=>`<div class="prop">
          <div class="verdict"><span class="lbl">${esc(v.p.label)}</span>${v.rule?`<span class="small muted">${v.rule.id} · ${esc(v.rule.name)}</span>`:""}
            <span class="small muted">model confidence ${v.p.confidence.toFixed(2)}</span>
            ${v.ok?`<span class="tag ok">accepted · ${money(c.j,v.amount)}${v.p.remainder?' (remainder)':''}</span>`:'<span class="tag bad">rejected</span>'}</div>
          <div class="small" style="margin-top:4px">${esc(v.p.rationale)}</div>
          <div class="small" style="margin-top:4px"><span class="muted">amount from</span> ${(v.p.amountFrom||[]).map(id=>recCite(c,id)).join("")||'<span class="muted">-</span>'} <span class="muted">· support</span> ${(v.p.support||[]).map(id=>recCite(c,id)).join("")||'<span class="muted">-</span>'}</div>
          ${v.why.map(w=>`<div class="notice bad">${esc(w)}</div>`).join("")}
        </div>`).join("")}
        ${x.flags.map(f=>`<div class="notice ${f.type==='conflict'?'bad':'warn'}">${f.type==='conflict'?'Conflict: ':'Reviewer: '}${esc(f.text)} ${f.src?cite(f.src):""}</div>`).join("")}
        ${x.suggest?`<div class="notice warn">${esc(x.suggest)}</div>`:""}
      `).join('<hr style="border:0;border-top:1px solid var(--line);margin:12px 0">')}
      <div class="small muted" style="margin-top:8px">Explained amounts come from cited records, never from model arithmetic. A variance closes only when the residue is exactly zero.</div>
    </section>`;

    // Stage 5
    h += `<section class="card stage llm"><h2>5 · Draft response <span class="tag llm">LLM, grounded</span><span class="tag det">citation + amount trace</span></h2>`;
    if(o.draftAllowed){
      const dc = o.draftChecks;
      const body = esc(c.draft).replace(/\{\{(\w+):(\d+)\}\}/g,(m,d,l)=>cite(`${d}:${l}`, !(c.docs[d] && +l<=c.docs[d].lines.length)));
      h += `<div class="small" style="margin-bottom:6px">Proposed position: <b>${o.overall}</b></div><div class="draft">${body}</div>
        <ul class="checks small" style="margin-top:8px">
          <li><span class="ic ${dc.cites.every(x=>x.ok)?'ok':'bad'}">${dc.cites.every(x=>x.ok)?'✓':'✗'}</span>${dc.cites.filter(x=>x.ok).length}/${dc.cites.length} citations resolve to a real source line</li>
          <li><span class="ic ${dc.amts.every(x=>x.ok)?'ok':'bad'}">${dc.amts.every(x=>x.ok)?'✓':'✗'}</span>${dc.amts.filter(x=>x.ok).length}/${dc.amts.length} currency amounts trace to an extracted or computed figure${dc.amts.filter(x=>!x.ok).map(x=>` · untraced: ${money(c.j,x.n)}`).join("")}</li>
        </ul>`;
    } else {
      h += `<div class="notice bad">Draft withheld. ${o.items.some(x=>!x.reproOk)?"The notice could not be reproduced. ":""}${o.items.some(x=>x.status==="residue")?"At least one variance has an unexplained residue. ":""}${o.items.some(x=>x.status==="conflict")?"A rule found a conflict in the return. ":""}The reviewer resolves these first; the model is not asked to write around them.</div>`;
